import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const Login = ({ setLoggedIn }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const handleLogin = (e) => {
    e.preventDefault();
    setLoggedIn(true);
    navigate("/");
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen text-center px-6">
      <h1 className="text-4xl font-bold mb-6 text-blue-100">Login</h1>
      <form
        onSubmit={handleLogin}
        className="bg-white/10 backdrop-blur-md p-6 rounded-lg shadow-lg w-full max-w-sm space-y-4"
      >
        <input
          type="email"
          placeholder="Email"
          className="w-full p-2 rounded bg-blue-800 text-white"
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          type="password"
          placeholder="Password"
          className="w-full p-2 rounded bg-blue-800 text-white"
          onChange={(e) => setPassword(e.target.value)}
        />
        <button type="submit" className="bg-blue-600 px-6 py-2 rounded-md text-white hover:bg-blue-700">
          Login
        </button>
      </form>
      <p className="mt-4 text-blue-300">
        Don’t have an account?{" "}
        <button onClick={() => navigate("/signup")} className="text-blue-400 underline">
          Sign up
        </button>
      </p>
    </div>
  );
};

export default Login;
